import os, json, re, time, glob

BEACONS_DIR = 'storage/shared/meta/sas/beacons'
PANEL_OUT   = 'storage/shared/meta/sas/dashboard/validation_results.json'
BUNDLE_IDX  = 'storage/shared/meta/sas/derived/bundle_index.json'

def _read_jsonl(path):
  rows = []
  try:
    with open(path, 'r', encoding='utf-8') as f:
      for line in f:
        line=line.strip()
        if not line: continue
        try: rows.append(json.loads(line))
        except Exception: pass
  except Exception:
    pass
  return rows

def _read_json(path):
  try:
    with open(path, 'r', encoding='utf-8') as f:
      obj = json.load(f)
    if isinstance(obj, list):
      return obj
    elif isinstance(obj, dict):
      return [obj]
    else:
      return []
  except Exception:
    return []

def _load_beacons():
  rows = []
  if not os.path.isdir(BEACONS_DIR):
    return rows
  for fp in glob.glob(os.path.join(BEACONS_DIR, '*')):
    if fp.endswith('.jsonl'):
      rows.extend(_read_jsonl(fp))
    elif fp.endswith('.json'):
      rows.extend(_read_json(fp))
  return rows

def _cost(d):
  # Prefer op_cost_ms, fallback to op_cost (assumed ms)
  v = d.get('op_cost_ms', d.get('op_cost'))
  try:
    return float(v) if v is not None else None
  except Exception:
    return None

def _note(d):
  return (d.get('notes') or d.get('phase_label') or '').lower()

def _agent(d):
  return (d.get('agent') or '').strip()

def mean(vals):
  return sum(vals) / len(vals) if vals else None

rows = _load_beacons()

# XL v0.5 (Zephyr V): notes like "XL:shallow_post_deep@+N"
xl_by_offset = {}
for r in rows:
  if _agent(r).lower() != 'zephyr v': 
    continue
  n = _note(r)
  if 'xl:shallow_post_deep@+' in n:
    m = re.search(r'@\+(\d+)', n)
    c = _cost(r)
    if m and c is not None:
      off = m.group(1)
      xl_by_offset.setdefault(off, []).append(c)

xl_means = {k: round(mean(v), 6) for k, v in xl_by_offset.items() if v}

# Define trough/peak sets for XL
trough_offsets = ['2', '6']
peak_offsets   = ['0', '4', '8']
t_vals = [xl_means.get(o) for o in trough_offsets if xl_means.get(o) is not None]
p_vals = [xl_means.get(o) for o in peak_offsets if xl_means.get(o) is not None]
trough_mean = round(mean(t_vals), 6) if t_vals else None
peak_mean   = round(mean(p_vals), 6) if p_vals else None
trough_vs_peak = round(trough_mean/peak_mean, 6) if (trough_mean is not None and peak_mean) else None

# SURR v0.5 (Nexus V): baseline "SURR_GPU:parallel_shallow"; offsets "SURR_GPU:parallel_shallow@+N"
surr_base_samples = []
surr_by_offset = {}
for r in rows:
  if _agent(r).lower() != 'nexus v':
    continue
  n = _note(r)
  c = _cost(r)
  if c is None: 
    continue
  if 'surr_gpu:parallel_shallow@+' in n:
    m = re.search(r'@\+(\d+)', n)
    if m:
      off = m.group(1)
      surr_by_offset.setdefault(off, []).append(c)
  elif 'surr_gpu:parallel_shallow' in n:
    surr_base_samples.append(c)

surr_base = round(mean(surr_base_samples), 6) if surr_base_samples else None
surr_means = {k: round(mean(v), 6) for k, v in surr_by_offset.items() if v}
surr_factors = {k: round(v/surr_base, 6) for k, v in surr_means.items()} if surr_base else {}

panel = {
  "title": "A/B Validation Results — v0.5 (CPU-only)",
  "updated_ts": time.time(),
  "xl_v0_5": {
    "agent": "Zephyr V",
    "means_ms_by_offset": xl_means,
    "trough_offsets": trough_offsets,
    "peak_offsets": peak_offsets,
    "trough_mean_ms": trough_mean,
    "peak_mean_ms": peak_mean,
    "trough_vs_peak_ratio": trough_vs_peak,
    "notes": [
      "Lower is better (ms). Expect troughs (+2,+6) < peaks (0,4,8).",
      "trough_vs_peak_ratio < 1 confirms trough efficiency."
    ]
  },
  "surr_v0_5": {
    "agent": "Nexus V",
    "baseline_ms": surr_base,
    "means_ms_by_offset": surr_means,
    "factors_vs_baseline": surr_factors,
    "notes": [
      "Factors < 1 indicate improvement vs baseline (lower ms). Expect +2 best, +6 ≈ baseline."
    ]
  }
}

os.makedirs(os.path.dirname(PANEL_OUT), exist_ok=True)
with open(PANEL_OUT, 'w', encoding='utf-8') as f:
  json.dump(panel, f, indent=2)

# Update bundle index with panel path
try:
  idx = {}
  if os.path.exists(BUNDLE_IDX):
    with open(BUNDLE_IDX, 'r', encoding='utf-8') as f:
      idx = json.load(f)
  idx = idx or {}
  v = idx.setdefault("validation", {})
  v["results_panel"] = PANEL_OUT
  idx["updated_ts"] = time.time()
  with open(BUNDLE_IDX, 'w', encoding='utf-8') as f:
    json.dump(idx, f, indent=2)
except Exception:
  pass

print(json.dumps({"panel_out": PANEL_OUT, "xl": panel["xl_v0_5"], "surr": panel["surr_v0_5"]}, indent=2))

